const size_t NormCompPairsCount = 961;


static const NormDecompIndex *NormBsearchIndex(
    const NormDecompIndex *idx, size_t count, uint32_t cp)
{
    size_t lo = 0, hi = count;
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2u;
        if (cp < idx[mid].cp) {
            hi = mid;
        } else if (cp > idx[mid].cp) {
            lo = mid + 1u;
        } else {
            return &idx[mid];
        }
    }
    return NULL;
}

const uint32_t *NormLookupCanon(uint32_t cp, size_t *len)
{
    const NormDecompIndex *e =
        NormBsearchIndex(NormCanonIndex, NormCanonIndexCount, cp);
    if (!e) {
        if (len) {
            *len = 0;
        }
        return NULL;
    }
    if (len) {
        *len = e->length;
    }
    return NormCanonData + e->offset;
}

const uint32_t *NormLookupCompat(uint32_t cp, size_t *len)
{
    const NormDecompIndex *e =
        NormBsearchIndex(NormCompatIndex, NormCompatIndexCount, cp);
    if (!e) {
        if (len) {
            *len = 0;
        }
        return NULL;
    }
    if (len) {
        *len = e->length;
    }
    return NormCompatData + e->offset;
}

uint32_t NormComposePair(uint32_t a, uint32_t b)
{
    size_t lo = 0, hi = NormCompPairsCount;
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2u;
        const NormCompPair *p = &NormCompPairs[mid];
        if (a < p->a || (a == p->a && b < p->b)) {
            hi = mid;
        } else if (a > p->a || (a == p->a && b > p->b)) {
            lo = mid + 1u;
        } else {
            return p->composite;
        }
    }
    return 0;
}

